import { LoginForm } from "./components/LoginForm";
import { Settings } from "./pages/Settings";
import "./styles/theme.css";

export function App({ signedIn }: { signedIn: boolean }) {
  return <main className="app">{signedIn ? <Settings /> : <LoginForm />}</main>;
}

import { useState } from "react";
import { createSession } from "../api/session";

export function LoginForm() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [remember, setRemember] = useState(false);

  async function submit(event: React.FormEvent) {
    event.preventDefault();
    await createSession({ email, password, remember });
  }

  return (
    <form onSubmit={submit}>
      <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} />
      <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} />
      <label>
        <input type="checkbox" checked={remember} onChange={(e) => setRemember(e.target.checked)} />
        Remember me
      </label>
      <button type="submit">Sign in</button>
    </form>
  );
}

const DAY = 24 * 60 * 60 * 1000;

export interface Credentials {
  email: string;
  password: string;
  remember?: boolean;
}

export async function createSession({ email, password, remember = false }: Credentials) {
  const response = await fetch("/api/session", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email, password }),
  });
  if (!response.ok) throw new Error("Sign-in failed");
  const lifetime = remember ? 30 * DAY : DAY;
  return { token: (await response.json()).token, expiresAt: Date.now() + lifetime };
}

export function isExpired(session: { expiresAt: number }) {
  return Date.now() >= session.expiresAt;
}

import { describe, expect, it, vi } from "vitest";
import { createSession, isExpired } from "./session";

const DAY = 24 * 60 * 60 * 1000;

describe("createSession", () => {
  it("keeps a session for one day by default", async () => {
    vi.stubGlobal("fetch", async () => new Response(JSON.stringify({ token: "t" })));
    const session = await createSession({ email: "a@example.com", password: "pw" });
    expect(session.expiresAt - Date.now()).toBeLessThanOrEqual(DAY);
  });

  it("keeps a remembered session for 30 days", async () => {
    vi.stubGlobal("fetch", async () => new Response(JSON.stringify({ token: "t" })));
    const session = await createSession({ email: "a@example.com", password: "pw", remember: true });
    expect(session.expiresAt - Date.now()).toBeGreaterThan(29 * DAY);
  });

  it("reports an expired session", () => {
    expect(isExpired({ expiresAt: Date.now() - 1 })).toBe(true);
  });
});

export function Settings() {
  return (
    <section className="settings">
      <h1>Settings</h1>
      <p>Account, notifications and appearance.</p>
    </section>
  );
}

